const base='images/combat/modular/';
function resolve(gear){
 const armorId=Number(gear?.armorId),weaponId=Number(gear?.weaponId),key=armorId+':'+weaponId;
 const armor=data.characters[armorId],weapon=data.weapons[weaponId],pose=weapon?.pose||'pistol';
 const character=armor?.poses?.[pose];
 if(!character||!weapon)return {key,armorId,weaponId,pose,ready:false};
 const adjustment=data.pairAdjustments[armorId+'-'+weaponId];
 return {key,armorId,weaponId,pose,ready:true,character,weapon,adjustment,
  body:base+'characters/'+armorId+'-'+pose+'.png',
  hands:base+'hands/'+armorId+'-'+pose+'.png',
  gun:base+'weapons/'+weaponId+'.png'};
}
async function load(gear,loadImage){
 if(!gear?.ready)return null;
 const [body,hands,gun]=await Promise.all([loadImage(gear.body),loadImage(gear.hands),loadImage(gear.gun)]);
 return {body,hands,gun,character:gear.character,weapon:gear.weapon,adjustment:gear.adjustment};
}
function draw(ctx,layers,side,offset=0){
 if(!layers||!['player','enemy'].includes(side))return false;
 const {body,hands,gun,character,weapon,adjustment}=layers;
 const scale=800/body.height, x=(side==='player'?340:1196)+offset;
 const size=weapon.scale*((adjustment?.size??100)/100);
 ctx.save();ctx.translate(x,940);ctx.scale((side==='enemy'?-1:1)*scale,scale);
 ctx.translate(-body.width/2,-body.height);
 ctx.drawImage(body,0,0);
 function drawGun(guard){
  ctx.save();ctx.translate(character.grip[0]+(adjustment?.dx||0),character.grip[1]+(adjustment?.dy||0));
  if(adjustment?.angle)ctx.rotate(adjustment.angle*Math.PI/180);
  ctx.scale(size,size);
  if(guard){ctx.beginPath();ctx.rect(guard[0]-weapon.grip[0],guard[1]-weapon.grip[1],guard[2],guard[3]);ctx.clip();}
  ctx.drawImage(gun,-weapon.grip[0],-weapon.grip[1]);ctx.restore();
 }
 drawGun();
 const arm=character.foregroundArm;
 if(weapon.pose==='heavy'&&Array.isArray(arm)&&arm.length>=3&&arm.every(p=>Array.isArray(p)&&p.length===2&&p.every(Number.isFinite))){
  ctx.save();ctx.beginPath();ctx.moveTo(arm[0][0],arm[0][1]);
  for(let i=1;i<arm.length;i++)ctx.lineTo(arm[i][0],arm[i][1]);
  ctx.closePath();ctx.clip();ctx.drawImage(body,0,0);ctx.restore();
 }
 const masks=character.handMasks;
 if(Array.isArray(masks)){
  // Trace only near-side fingers on the original body; old hand crops can omit fingertips.
  const outlines=masks.filter(p=>Array.isArray(p)&&p.length>=3&&p.every(v=>Array.isArray(v)&&v.length===2&&v.every(Number.isFinite)));
  if(outlines.length){
   ctx.save();ctx.beginPath();
   for(const outline of outlines){ctx.moveTo(outline[0][0],outline[0][1]);for(let i=1;i<outline.length;i++)ctx.lineTo(outline[i][0],outline[i][1]);ctx.closePath();}
   ctx.clip();ctx.drawImage(body,0,0);ctx.restore();
  }
 }else ctx.drawImage(hands,0,0);
 const guard=weapon.foregroundGuard;
 if(Array.isArray(guard)&&guard.length===4&&guard.every(Number.isFinite)&&guard[2]>0&&guard[3]>0)drawGun(guard);
 ctx.restore();return true;
}
